// One continuous keyboard in both dock and fullscreen; scroll changes the view, never pitch.
let webPianoZoom='4',webPianoOffset=0,webPianoUnit=1,webPianoFrame=0,webPianoResize=null;
const webZoomOptions='<option value="4">常用宽键</option><option value="3">约三八度</option><option value="2">约两八度</option><option value="1">约一八度</option><option value="all">全部 49 键</option>';
$('#fullPianoOctaves').innerHTML=webZoomOptions;$('#fullPianoOctaves').parentElement.firstChild.textContent='琴键宽度';$('#fullPianoBandLabel').hidden=true;
function webPianoSync(){const viewport=$('#webKeyViewport');if(!viewport||!viewport.clientWidth)return;const bounds=viewport.getBoundingClientRect();webPianoOffset=viewport.scrollLeft/webPianoUnit;const slider=$('#webPianoScroll');slider.max=Math.max(0,viewport.scrollWidth-viewport.clientWidth);slider.value=viewport.scrollLeft;slider.disabled=viewport.scrollWidth<=viewport.clientWidth+1;const visible=$$('#liveKeyboard .live-key').filter(k=>{const r=k.getBoundingClientRect();return Math.min(r.right,bounds.right)-Math.max(r.left,bounds.left)>=r.width*.5});if(visible.length){const range=pianoNoteName((octave+1)*12+(+visible[0].dataset.offset))+' — '+pianoNoteName((octave+1)*12+(+visible[visible.length-1].dataset.offset));$('#webVisibleRange').textContent=range+' · 全部 49 键保留';$('#octLabel').textContent=range;if(pianoFullscreenOpen)$('#fullPianoRange').textContent=range}const total=pocketMidi().length,count=visible.filter(k=>k.classList.contains('chord-reference')).length;$('#webScrollHint').textContent=total&&count<total?`当前可见 ${count}/${total} 个和弦音 · 拖动查看更多`:'拖动滑条查看两端琴键';}
function webRevealChord(){const viewport=$('#webKeyViewport'),refs=$$('#liveKeyboard .chord-reference');if(!viewport||!refs.length){webPianoSync();return}const first=refs[0],last=refs[refs.length-1],left=first.offsetLeft,right=last.offsetLeft+last.offsetWidth;if(right-left>viewport.clientWidth)viewport.scrollLeft=left;else if(right>viewport.scrollLeft+viewport.clientWidth)viewport.scrollLeft=right-viewport.clientWidth;else if(left<viewport.scrollLeft)viewport.scrollLeft=left;webPianoSync()}
pianoKeys=function(){webPianoResize?.disconnect();const base=(octave+1)*12,start=pianoReferenceStart(base),end=start+48,white=m=>![1,3,6,8,10].includes(m%12),nums=Array.from({length:49},(_,i)=>start+i),units=nums.filter(white).length+(white(start)?0:.5)+(white(end)?0:.5),view=Math.min(units,webPianoZoom==='all'?units:webPianoZoom==='4'?24.5:webPianoZoom==='3'?22:webPianoZoom==='2'?15:8);$('#liveKeyboard').innerHTML=`<div class="web-piano-view"><span id="webVisibleRange"></span><label class="web-zoom-label">琴键宽度 <select id="webPianoZoom">${webZoomOptions}</select></label></div><div class="web-piano-scrollbar"><span>低音</span><input id="webPianoScroll" type="range" min="0" max="1" step="1" value="0" aria-label="横向移动钢琴可视音区"><span>高音</span><small id="webScrollHint">拖动滑条查看两端琴键</small></div><div id="webKeyViewport" style="--web-key-width:${units/view*100}%">${continuousKeyRow(start,end,base,true)}</div>`;$('#webPianoZoom').value=webPianoZoom;$('#fullPianoOctaves').value=webPianoZoom;$('#fullPianoBandLabel').hidden=true;$('#pianoPanel .piano-toolbar small').textContent='49 键完整保留 · 滑条移动可视音区';const viewport=$('#webKeyViewport'),row=viewport.firstElementChild;webPianoUnit=Math.max(1,row.getBoundingClientRect().width/units);viewport.scrollLeft=webPianoOffset*webPianoUnit;$('#webPianoScroll').oninput=()=>{viewport.scrollLeft=+$('#webPianoScroll').value;webPianoSync()};viewport.addEventListener('scroll',()=>{cancelAnimationFrame(webPianoFrame);webPianoFrame=requestAnimationFrame(webPianoSync)});$('#webPianoZoom').onchange=e=>setWebPianoZoom(e.target.value);pocketPaint();liveVisual();webPianoSync();webPianoResize=new ResizeObserver(()=>{if(!viewport.clientWidth)return;webPianoUnit=row.getBoundingClientRect().width/units;viewport.scrollLeft=webPianoOffset*webPianoUnit;webPianoSync()});webPianoResize.observe(viewport);};
function setWebPianoZoom(value){releaseAll();webPianoZoom=value;pianoKeys()}
$('#fullPianoOctaves').onchange=e=>setWebPianoZoom(e.target.value);
// All 49 notes are present at every zoom level, so querying must not collapse the key width.
pocketFit=function(){};const sliderPocketRefresh=pocketRefresh;pocketRefresh=function(){sliderPocketRefresh();webRevealChord()};
const sliderChangeOctave=changeOctave;changeOctave=function(delta){webPianoOffset=0;sliderChangeOctave(delta)};pianoKeys();
